func TestRuntimeRouterUnifiedExecEventsMapToRustV2Notifications(t *testing.T) {
	store := session.NewStore(filepath.Join(t.TempDir(), "sessions"))
	if err := store.Save(&session.Record{ID: "thread-unified", CreatedAt: time.Now().UTC()}); err != nil {
		t.Fatalf("save thread: %v", err)
	}
	sink := NewNotificationBuffer()
	analyticsSink := newRecordingTurnEventSink()
	router := NewRuntimeRouter(RuntimeServices{
		ThreadRouter: NewRouter(store),
		Analytics:    analyticsSink,
	})
	defer router.Close()
	router.SetNotificationSink(sink)
	router.clientInfo["conn-unified"] = ClientInfo{Name: "codex-tui", Version: "1.2.3"}
	router.active["thread-unified"] = &activeRuntimeTurn{
		ThreadID:     "thread-unified",
		TurnID:       "turn-unified",
		ConnectionID: "conn-unified",
		RunConfig:    &appTurnRunConfig{},
	}
	emit := router.runtimeUnifiedExecEventSink("thread-unified", "turn-unified")
	startedAt := time.Now().Add(-time.Second).UTC()

	emit(tool.UnifiedExecEvent{
		Kind:        tool.UnifiedExecEventBegin,
		CallID:      "call-unified",
		HookCommand: "printf hello",
		CWD:         t.TempDir(),
		ProcessID:   42,
		StartedAt:   startedAt,
	})
	emit(tool.UnifiedExecEvent{Kind: tool.UnifiedExecEventOutputDelta, CallID: "call-unified", ProcessID: 42, Output: "hello"})
	emit(tool.UnifiedExecEvent{Kind: tool.UnifiedExecEventTerminalInteraction, CallID: "call-unified", ProcessID: 42, Input: "quit\n"})
	emit(tool.UnifiedExecEvent{
		Kind:        tool.UnifiedExecEventEnd,
		CallID:      "call-unified",
		HookCommand: "printf hello",
		CWD:         t.TempDir(),
		ProcessID:   42,
		Output:      "hello",
		ExitCode:    7,
		Duration:    1500 * time.Millisecond,
		StartedAt:   startedAt,
	})

	notifications := sink.List()
	if len(notifications) != 4 {
		t.Fatalf("notifications = %#v", notifications)
	}
	started, ok := notifications[0].Params.(*ItemStartedNotification)
	if !ok || notifications[0].Method != NotificationItemStarted || started.ThreadID != "thread-unified" || started.TurnID != "turn-unified" {
		t.Fatalf("started notification = %#v", notifications[0])
	}
	if started.Item["id"] != "call-unified" || started.Item["source"] != string(CommandExecutionSourceUnifiedExecStartup) || started.Item["processId"] != "42" || started.Item["status"] != string(CommandExecutionInProgress) {
		t.Fatalf("started item = %#v", started.Item)
	}
	delta, ok := notifications[1].Params.(*CommandExecutionOutputDeltaNotification)
	if !ok || notifications[1].Method != NotificationCommandExecutionOutputDelta || delta.ItemID != "call-unified" || delta.Delta != "hello" {
		t.Fatalf("delta notification = %#v", notifications[1])
	}
	interaction, ok := notifications[2].Params.(*TerminalInteractionNotification)
	if !ok || notifications[2].Method != NotificationTerminalInteraction || interaction.ItemID != "call-unified" || interaction.ProcessID != "42" || interaction.Stdin != "quit\n" {
		t.Fatalf("interaction notification = %#v", notifications[2])
	}
	completed, ok := notifications[3].Params.(*ItemCompletedNotification)
	if !ok || notifications[3].Method != NotificationItemCompleted {
		t.Fatalf("completed notification = %#v", notifications[3])
	}
	if completed.Item["id"] != "call-unified" || completed.Item["status"] != string(CommandExecutionFailed) || completed.Item["exitCode"] != float64(7) || completed.Item["aggregatedOutput"] != "hello" {
		t.Fatalf("completed item = %#v", completed.Item)
	}
	analytics := waitForCommandExecutionAnalyticsEvent(t, analyticsSink, "turn-unified").EventParams
	if analytics.ItemID != "call-unified" || analytics.ToolName != "unified_exec" || analytics.CommandExecutionSource != "unified_exec_startup" || analytics.ExitCode == nil || *analytics.ExitCode != 7 {
		t.Fatalf("unified exec analytics = %#v", analytics)
	}
	if analytics.StartedAtMS != uint64(startedAt.UnixMilli()) || analytics.CompletedAtMS != uint64(startedAt.Add(1500*time.Millisecond).UnixMilli()) || analytics.ExecutionDurationMS == nil || *analytics.ExecutionDurationMS != 1500 {
		t.Fatalf("unified exec analytics timing = %#v", analytics)
	}

	if shouldNotifyRuntimeItemCompleted(ThreadItem{Type: "tool_output", Data: map[string]any{"unified_exec_evented": true}}) {
		t.Fatal("evented unified exec output should not emit a duplicate completed notification")
	}
	pending := router.drainPendingUnifiedExecItems("thread-unified", "turn-unified")
	if len(pending) != 1 || pending[0].ID != "call-unified" || pending[0].Type != "commandExecution" || !boolFromAny(pending[0].Data["unified_exec_evented"]) {
		t.Fatalf("pending unified exec items = %#v", pending)
	}
	if _, err := router.runtimeAppendItems("thread-unified", pending); err != nil {
		t.Fatalf("persist pending unified exec items: %v", err)
	}

	if _, err := store.AppendItem("thread-unified", session.Item{
		ID:       "transport-output",
		Type:     "tool_output",
		Text:     "model transport",
		Data:     map[string]any{"command": "printf hello"},
		Metadata: map[string]any{"turnId": "turn-unified", "hiddenFromThread": true},
	}); err != nil {
		t.Fatalf("append hidden transport: %v", err)
	}
	record, err := store.Load("thread-unified")
	if err != nil {
		t.Fatalf("load thread: %v", err)
	}
	items, err := BuildItemsResponse(record, &ThreadItemsListParams{ThreadID: "thread-unified"})
	if err != nil {
		t.Fatalf("BuildItemsResponse() error = %v", err)
	}
	if len(items.Data) != 1 || threadItemWireType(&items.Data[0].Item) != "commandExecution" || items.Data[0].Item.ID != "call-unified" {
		t.Fatalf("visible persisted items = %#v", items.Data)
	}
}

func TestRuntimeRouterUnifiedExecEndNotifiesBeforeBlockedPersistenceLikeRust(t *testing.T) {
	sink := NewNotificationBuffer()
	router := NewRuntimeRouter(RuntimeServices{ThreadRouter: NewRouter(session.NewStore(t.TempDir()))})
	defer router.Close()
	router.SetNotificationSink(sink)
	router.active["thread-live"] = &activeRuntimeTurn{ThreadID: "thread-live", TurnID: "turn-live"}

	// A held persistence-order lock models a slow session store/rollout writer.
	// Client-visible completion must still be emitted and the event sink must
	// return, matching Rust's event-first lifecycle.
	router.unifiedExecPersistMu.Lock()
	done := make(chan struct{})
	go func() {
		router.runtimeUnifiedExecEventSink("thread-live", "turn-live")(tool.UnifiedExecEvent{
			Kind:      tool.UnifiedExecEventEnd,
			CallID:    "call-live",
			Command:   []string{"echo", "live"},
			ProcessID: 1,
			ExitCode:  0,
			StartedAt: time.Now().Add(-time.Second),
			Duration:  time.Second,
		})
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(time.Second):
		router.unifiedExecPersistMu.Unlock()
		t.Fatal("unified exec end sink blocked behind persistence")
	}
	completed := 0
	for _, notification := range sink.List() {
		if notification.Method == NotificationItemCompleted {
			payload, _ := notification.Params.(*ItemCompletedNotification)
			if payload != nil && payload.Item["id"] == "call-live" {
				completed++
			}
		}
	}
	router.unifiedExecPersistMu.Unlock()
	if completed != 1 {
		t.Fatalf("completed notifications = %d, want 1", completed)
	}
}

func TestRuntimeRouterUnifiedExecEndAfterTurnPersistsLateBackgroundCompletion(t *testing.T) {
	store := session.NewStore(t.TempDir())
	if err := store.Save(&session.Record{ID: "thread-background-end", CreatedAt: time.Now().UTC()}); err != nil {
		t.Fatal(err)
	}
	router := NewRuntimeRouter(RuntimeServices{ThreadRouter: NewRouter(store)})
	defer router.Close()
	router.runtimeUnifiedExecEventSink("thread-background-end", "turn-background-end")(tool.UnifiedExecEvent{
		Kind:      tool.UnifiedExecEventEnd,
		CallID:    "call-background-end",
		Command:   []string{"echo", "background"},
		ProcessID: 9,
		Output:    "background\n",
		ExitCode:  0,
		StartedAt: time.Now().Add(-time.Second),
		Duration:  time.Second,
	})
	if pending := router.drainPendingUnifiedExecItems("thread-background-end", "turn-background-end"); len(pending) != 0 {
		t.Fatalf("late background pending items = %#v", pending)
	}
	record, err := store.Load("thread-background-end")
	if err != nil {
		t.Fatal(err)
	}
	completed := 0
	for _, item := range record.Items {
		if item.ID == "call-background-end" && item.Type == "commandExecution" {
			completed++
		}
	}
	if completed != 1 {
		t.Fatalf("persisted late background completions = %d, items=%#v", completed, record.Items)
	}
}

func TestRuntimeRouterMCPToolStartedMapsToRustV2Notification(t *testing.T) {
	sink := NewNotificationBuffer()
	router := NewRuntimeRouter(RuntimeServices{})
	defer router.Close()
	router.SetNotificationSink(sink)
	startedAt := time.Now().UTC()

	notify := router.runtimeToolStartedNotifier("thread-mcp", "turn-mcp", t.TempDir(), false)
	invocation := &tool.Invocation{
		CallID:   "call-mcp",
		ToolName: tool.NamespacedName("mcp__geogebra", "geogebra_create_point"),
		Payload:  tool.Payload{Kind: tool.PayloadFunction, Arguments: `{"label":"A"}`},
		Context:  map[string]any{"read_only_hint": true},
	}
	notify(context.Background(), invocation, startedAt)

	notifications := sink.List()
	if len(notifications) != 1 || notifications[0].Method != NotificationItemStarted {
		t.Fatalf("MCP start notifications = %#v", notifications)
	}
	started, ok := notifications[0].Params.(*ItemStartedNotification)
	if !ok {
		t.Fatalf("MCP start notification = %#v", notifications[0])
	}
	if started.Item["id"] != "call-mcp" || started.Item["type"] != "mcpToolCall" || started.Item["server"] != "geogebra" || started.Item["tool"] != "geogebra_create_point" || started.Item["status"] != "inProgress" {
		t.Fatalf("MCP start item = %#v", started.Item)
	}
	arguments, ok := started.Item["arguments"].(map[string]any)
	if !ok || arguments["label"] != "A" {
		t.Fatalf("MCP start arguments = %#v", started.Item["arguments"])
	}
	if started.Item["readOnlyHint"] != true {
		t.Fatalf("MCP start readOnlyHint = %#v", started.Item["readOnlyHint"])
	}

	encoded, err := json.Marshal(&ThreadItem{ID: "call-mcp", Type: "mcpToolCall", Data: map[string]any{
		"server": "geogebra", "tool": "geogebra_create_point", "status": "completed", "read_only_hint": true,
	}})
	if err != nil {
		t.Fatalf("Marshal MCP item error = %v", err)
	}
	var persisted map[string]any
	if err := json.Unmarshal(encoded, &persisted); err != nil {
		t.Fatalf("Unmarshal MCP item error = %v", err)
	}
	if persisted["readOnlyHint"] != true {
		t.Fatalf("persisted MCP readOnlyHint = %#v in %#v", persisted["readOnlyHint"], persisted)
	}
}

func TestRuntimeRouterCodeModeNestedCommandLifecycleIsVisibleToTUI(t *testing.T) {
	sink := NewNotificationBuffer()
	router := NewRuntimeRouter(RuntimeServices{})
	defer router.Close()
	router.SetNotificationSink(sink)
	startedAt := time.Now().UTC()
	invocation := &tool.Invocation{
		CallID:   "nested-command",
		ToolName: tool.PlainName(tool.DefaultExecCommandToolName),
		Payload:  tool.Payload{Kind: tool.PayloadFunction, Arguments: `{"cmd":"Write-Output weather"}`},
		Source:   "code_mode",
	}
	router.runtimeToolStartedNotifier("thread-code", "turn-code", t.TempDir(), false)(context.Background(), invocation, startedAt)
	router.runtimeToolCompletedNotifier("thread-code", "turn-code", t.TempDir(), false)(context.Background(), &turn.ToolExecutionResult{
		Invocation: invocation,
		Output: &tool.Output{Success: true, Body: "weather\n", Data: map[string]any{
			"hook_response": "weather\n",
			"exit_code":     0,
		}},
		StartedAt:  startedAt,
		FinishedAt: startedAt.Add(time.Second),
	})

	notifications := sink.List()
	if len(notifications) != 2 || notifications[0].Method != NotificationItemStarted || notifications[1].Method != NotificationItemCompleted {
		t.Fatalf("nested command notifications = %#v", notifications)
	}
	completed, ok := notifications[1].Params.(*ItemCompletedNotification)
	if !ok {
		t.Fatalf("nested command completion = %#v", notifications[1])
	}
	if completed.Item["id"] != "nested-command" || completed.Item["type"] != "commandExecution" || completed.Item["status"] != string(CommandExecutionCompleted) || completed.Item["aggregatedOutput"] != "weather\n" || intFromAny(completed.Item["exitCode"]) != 0 {
		t.Fatalf("nested command completed item = %#v", completed.Item)
	}
}

func TestRuntimeRouterCodeModeNestedCommandLifecycleIsVisibleWithUnifiedExec(t *testing.T) {
	sink := NewNotificationBuffer()
	router := NewRuntimeRouter(RuntimeServices{})
	defer router.Close()
	router.SetNotificationSink(sink)
	startedAt := time.Now().UTC()
	invocation := &tool.Invocation{
		CallID:   "nested-unified-command",
		ToolName: tool.PlainName(tool.DefaultExecCommandToolName),
		Payload:  tool.Payload{Kind: tool.PayloadFunction, Arguments: `{"cmd":"Write-Output weather"}`},
		Source:   "code_mode",
	}
	router.runtimeToolStartedNotifier("thread-code", "turn-code", t.TempDir(), true)(context.Background(), invocation, startedAt)
	router.runtimeToolCompletedNotifier("thread-code", "turn-code", t.TempDir(), true)(context.Background(), &turn.ToolExecutionResult{
		Invocation: invocation,
		Output: &tool.Output{Success: true, Body: "weather\n", Data: map[string]any{
			"hook_response": "weather\n",
			"exit_code":     0,
		}},
		StartedAt:  startedAt,
		FinishedAt: startedAt.Add(time.Second),
	})

	// When unified exec is enabled, its event sink owns the command lifecycle.
	// The dispatcher callback must stay silent or the real path emits duplicate
	// item/started and item/completed notifications.
	if notifications := sink.List(); len(notifications) != 0 {
		t.Fatalf("nested unified callback notifications = %#v, want none", notifications)
	}
}

func TestRuntimeRouterCodeModeExecEndToEndEmitsOneNestedCommandLifecycleAndOneFinalMessage(t *testing.T) {
	store := session.NewStore(t.TempDir())
	sink := NewNotificationBuffer()
	var responseMu sync.Mutex
	responseNumber := 0
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		responseMu.Lock()
		responseNumber++
		current := responseNumber
		responseMu.Unlock()
		w.Header().Set("Content-Type", "text/event-stream")
		if current == 1 {
			_, _ = w.Write([]byte(modelResponsesSSE(
				`{"type":"response.created","response":{"id":"resp-code-mode"}}`,
				`{"type":"response.output_item.added","item":{"id":"outer-exec","type":"custom_tool_call","call_id":"outer-exec","name":"exec","input":"const r = await tools.exec_command({\"cmd\":\"echo weather\"}); text(r.output);"}}`,
				`{"type":"response.output_item.done","item":{"id":"outer-exec","type":"custom_tool_call","call_id":"outer-exec","name":"exec","input":"const r = await tools.exec_command({\"cmd\":\"echo weather\"}); text(r.output);"}}`,
				`{"type":"response.completed","response":{"id":"resp-code-mode","usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}}}`,
			)))
			return
		}
		_, _ = w.Write([]byte(modelResponsesSSE(
			`{"type":"response.created","response":{"id":"resp-final"}}`,
			`{"type":"response.output_item.added","item":{"id":"msg-final","type":"message","role":"assistant","content":[{"type":"output_text","text":""}]}}`,
			`{"type":"response.output_text.delta","delta":"done"}`,
			`{"type":"response.output_item.done","item":{"id":"msg-final","type":"message","role":"assistant","content":[{"type":"output_text","text":"done"}]}}`,
			`{"type":"response.completed","response":{"id":"resp-final","usage":{"input_tokens":1,"output_tokens":1,"total_tokens":2}}}`,
		)))
	}))
	defer server.Close()
	agent := model.NewResponsesAgentRunner(&model.ResponsesAgentOptions{
		Provider: &model.APIProvider{BaseURL: server.URL + "/v1"},
		Stream:   true,
	})
	router := NewRuntimeRouter(RuntimeServices{
		ThreadRouter: NewRouter(store),
		Turns:        turn.NewTurnService(),
		Agent:        agent,
		ThreadStatus: NewThreadStatusManager(),
	})
	defer router.Close()
	router.SetNotificationSink(sink)

	threadStart := router.Handle(requestWithParams(t, IntID(1), MethodThreadStart, ThreadStartParams{CWD: t.TempDir()}))
	if threadStart.Error != nil {
		t.Fatalf("thread start error: %+v", threadStart.Error)
	}
	threadID := threadStart.Result.(*ThreadStartResponse).Thread.ID
	turnStart := router.Handle(requestWithParams(t, IntID(2), MethodTurnStart, turn.TurnStartParams{
		ThreadID: threadID,
		Prompt:   "run code mode command",
		Config: map[string]any{
			"features": map[string]any{"code_mode": true, "unified_exec": true},
		},
	}))
	if turnStart.Error != nil {
		t.Fatalf("turn start error: %+v", turnStart.Error)
	}
	turnID := turnStart.Result.(*turn.TurnStartResponse).Turn.ID
	waitForTurnCompletedStatus(t, sink, turnID, TurnStatusCompleted)

	nestedStarted := 0
	nestedCompleted := 0
	finalDeltas := []string{}
	finalCompleted := 0
	nestedStartedIndex := -1
	nestedCompletedIndex := -1
	finalCompletedIndex := -1
	turnCompletedIndex := -1
	for index, notification := range sink.List() {
		switch notification.Method {
		case NotificationItemStarted:
			payload, _ := notification.Params.(*ItemStartedNotification)
			if payload != nil && payload.TurnID == turnID && payload.Item["type"] == "commandExecution" && strings.Contains(stringFromAny(payload.Item["command"]), "echo weather") {
				nestedStarted++
				if nestedStartedIndex < 0 {
					nestedStartedIndex = index
				}
			}
		case NotificationItemCompleted:
			payload, _ := notification.Params.(*ItemCompletedNotification)
			if payload == nil || payload.TurnID != turnID {
				continue
			}
			if payload.Item["type"] == "commandExecution" && strings.Contains(stringFromAny(payload.Item["command"]), "echo weather") {
				nestedCompleted++
				if nestedCompletedIndex < 0 {
					nestedCompletedIndex = index
				}
			}
			if payload.Item["type"] == "agentMessage" && payload.Item["id"] == "msg-final" {
				finalCompleted++
				if finalCompletedIndex < 0 {
					finalCompletedIndex = index
				}
			}
		case NotificationAgentMessageDelta:
			payload, _ := notification.Params.(*AgentMessageDeltaNotification)
			if payload != nil && payload.TurnID == turnID && payload.ItemID == "msg-final" {
				finalDeltas = append(finalDeltas, payload.Delta)
			}
		case NotificationTurnCompleted:
			payload, _ := notification.Params.(*TurnCompletedNotification)
			if payload != nil && payload.Turn.ID == turnID && turnCompletedIndex < 0 {
				turnCompletedIndex = index
			}
		}
	}
	if nestedStarted != 1 || nestedCompleted != 1 {
		t.Fatalf("nested command lifecycle = %d started/%d completed, notifications=%#v", nestedStarted, nestedCompleted, sink.List())
	}
	if !reflect.DeepEqual(finalDeltas, []string{"done"}) || finalCompleted != 1 {
		t.Fatalf("final lifecycle deltas=%#v completed=%d, notifications=%#v", finalDeltas, finalCompleted, sink.List())
	}
	if !(nestedStartedIndex < nestedCompletedIndex && nestedCompletedIndex < finalCompletedIndex && finalCompletedIndex < turnCompletedIndex) {
		t.Fatalf("lifecycle order started=%d command-completed=%d final-completed=%d turn-completed=%d, notifications=%#v", nestedStartedIndex, nestedCompletedIndex, finalCompletedIndex, turnCompletedIndex, sink.List())
	}
	responseMu.Lock()
	gotResponses := responseNumber
	responseMu.Unlock()
	if gotResponses != 2 {
		t.Fatalf("model response count = %d, want 2", gotResponses)
	}
	if pending := router.drainPendingUnifiedExecItems(threadID, turnID); len(pending) != 0 {
		t.Fatalf("pending unified exec items after turn completion = %#v", pending)
	}
	persisted, err := store.Load(session.ThreadID(threadID))
	if err != nil {
		t.Fatalf("load completed thread: %v", err)
	}
	persistedCommands := 0
	persistedFinals := 0
	for _, item := range persisted.Items {
		if item.ID == "outer-exec-nested-1" && item.Type == "commandExecution" {
			persistedCommands++
			if !boolFromAny(item.Data["unified_exec_evented"]) {
				t.Fatalf("persisted command missing unified_exec_evented: %#v", item)
			}
		}
		if item.ID == "msg-final" && item.Type == "agent_message" {
			persistedFinals++
		}
	}
	if persistedCommands != 1 || persistedFinals != 1 {
		t.Fatalf("persisted lifecycle = %d commands/%d finals, items=%#v", persistedCommands, persistedFinals, persisted.Items)
	}
}

func TestRuntimeRouterUnifiedExecBackgroundTerminalHelper(t *testing.T) {
	if os.Getenv("CODEX_GO_UNIFIED_EXEC_BACKGROUND_HELPER") != "1" {
		return
	}
	time.Sleep(30 * time.Second)
}

func TestRuntimeRouterBackgroundTerminalsIncludeThreadScopedUnifiedExecLikeRust(t *testing.T) {
	manager := tool.NewUnifiedExecManagerWithOptions(2, 5_000)
	defer manager.Close()
	result, err := manager.Exec(context.Background(), &tool.ShellRequest{
		Command:             []string{os.Args[0], "-test.run=^TestRuntimeRouterUnifiedExecBackgroundTerminalHelper$"},
		HookCommand:         "background helper",
		CWD:                 t.TempDir(),
		Env:                 map[string]string{"CODEX_GO_UNIFIED_EXEC_BACKGROUND_HELPER": "1"},
		YieldTimeMS:         250,
		TimeoutMS:           15_000,
		UnifiedExecThreadID: "thread-background",
		UnifiedExecTurnID:   "turn-background",
	}, "call-background")
	if err != nil || result.ProcessID == nil {
		t.Fatalf("Exec() = %#v, %v", result, err)
	}

	extras := NewThreadExtraService()
	extras.SetBackgroundTerminals("thread-background", []BackgroundTerminal{{
		ItemID: "user-shell", ProcessID: "900", Command: "user shell", CWD: t.TempDir(),
	}})
	router := NewRuntimeRouter(RuntimeServices{ThreadExtras: extras, UnifiedExec: manager})
	defer router.Close()

	listed, err := router.listBackgroundTerminals(&BackgroundTerminalsListParams{ThreadID: "thread-background"})
	if err != nil {
		t.Fatalf("listBackgroundTerminals() error = %v", err)
	}
	if len(listed.Data) != 2 || listed.Data[0].ProcessID != strconv.Itoa(*result.ProcessID) || listed.Data[0].ItemID != "call-background" || listed.Data[0].Command != "background helper" || listed.Data[1].ProcessID != "900" {
		t.Fatalf("background terminals = %#v", listed.Data)
	}
	other, err := router.listBackgroundTerminals(&BackgroundTerminalsListParams{ThreadID: "thread-other"})
	if err != nil || len(other.Data) != 0 {
		t.Fatalf("other thread terminals = %#v, %v", other, err)
	}

	terminated, err := router.terminateBackgroundTerminal(&BackgroundTerminalsTerminateParams{
		ThreadID: "thread-background", ProcessID: strconv.Itoa(*result.ProcessID),
	})
	if err != nil || !terminated.Terminated {
		t.Fatalf("terminateBackgroundTerminal() = %#v, %v", terminated, err)
	}
	if _, err := router.cleanBackgroundTerminals(&BackgroundTerminalsCleanParams{ThreadID: "thread-background"}); err != nil {
		t.Fatalf("cleanBackgroundTerminals() error = %v", err)
	}
	listed, err = router.listBackgroundTerminals(&BackgroundTerminalsListParams{ThreadID: "thread-background"})
	if err != nil || len(listed.Data) != 0 {
		t.Fatalf("terminals after clean = %#v, %v", listed, err)
	}
}

type appServerExecServerURLWriter struct {
	once sync.Once
	url  chan string
}

func (w *appServerExecServerURLWriter) Write(data []byte) (int, error) {
	w.once.Do(func() { w.url <- strings.TrimSpace(string(data)) })
	return len(data), nil
}

func TestRuntimeRouterUnifiedExecUsesSelectedRemoteEnvironmentLikeRust(t *testing.T) {
	serverCtx, cancelServer := context.WithCancel(context.Background())
	urlCh := make(chan string, 1)
	serverDone := make(chan error, 1)
	go func() {
		serverDone <- execserver.NewServer().ServeTransport(serverCtx, "ws://127.0.0.1:0", nil, &appServerExecServerURLWriter{url: urlCh})
	}()
	var execServerURL string
	select {
	case execServerURL = <-urlCh:
	case <-time.After(3 * time.Second):
		t.Fatal("exec-server URL was not reported")
	}
	defer func() {
		cancelServer()
		select {
		case err := <-serverDone:
			if err != nil {
				t.Errorf("exec-server shutdown error = %v", err)
			}
		case <-time.After(3 * time.Second):
			t.Error("exec-server did not stop")
		}
	}()

	home := t.TempDir()
	configBody := "sandbox_mode = \"workspace-write\"\n" +
		"[features]\nunified_exec = true\n" +
		"[network_proxy]\n" +
		"enabled = true\n" +
		"proxy_url = \"http://127.0.0.1:0\"\n" +
		"enable_socks5 = false\n" +
		"mode = \"full\"\n"
	if err := os.WriteFile(config.ConfigPath(home), []byte(configBody), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}
	cwd := t.TempDir()
	shellInfo := EnvironmentShellInfo{Name: "bash", Path: "/bin/bash"}
	if runtime.GOOS == "windows" {
		shellInfo = EnvironmentShellInfo{Name: "powershell", Path: "powershell"}
	}
	environments := NewEnvironmentManager(shellInfo, cwd)
	for _, id := range []string{"remote-primary", "remote-secondary"} {
		if _, err := environments.Add(&EnvironmentAddParams{EnvironmentID: id, ExecServerURL: execServerURL}); err != nil {
			t.Fatalf("add environment %s: %v", id, err)
		}
		if err := environments.SetInfo(id, shellInfo, cwd); err != nil {
			t.Fatalf("set environment info %s: %v", id, err)
		}
	}
	router := NewRuntimeRouter(RuntimeServices{
		Config:                     config.NewConfigService(home),
		Environment:                environments,
		ManagedNetworkRequirements: &config.NetworkRequirements{Enabled: boolPtr(true)},
	})
	defer router.Close()
	params := &turn.TurnStartParams{
		ThreadID:       "thread-remote-environment",
		ApprovalPolicy: sandbox.ApprovalNever,
		SandboxPolicy:  string(sandbox.SandboxDangerFullAccess),
		Environments: []map[string]any{
			{"environmentId": "remote-primary", "cwd": cwd},
			{"environmentId": "remote-secondary", "cwd": cwd},
		},
	}
	toolRouter, err := router.toolRouterForTurn(cwd, params, "turn-remote-environment")
	if err != nil {
		t.Fatalf("toolRouterForTurn() error = %v", err)
	}
	visibleSpecs := toolRouter.ModelVisibleSpecs()
	var codeModeSpec *tool.Spec
	for i := range visibleSpecs {
		if visibleSpecs[i].Name.Key() == tool.CodeModeExecToolName {
			codeModeSpec = &visibleSpecs[i]
			break
		}
	}
	if codeModeSpec == nil || !strings.Contains(codeModeSpec.Description, "tools.exec_command") || !strings.Contains(codeModeSpec.Description, `"environment_id"`) {
		t.Fatalf("code-mode exec spec = %#v", codeModeSpec)
	}
	for i := range visibleSpecs {
		if visibleSpecs[i].Name.Key() == tool.DefaultExecCommandToolName || visibleSpecs[i].Name.Key() == tool.DefaultShellCommandToolName {
			t.Fatalf("nested command leaked as a top-level model-visible tool: %#v", visibleSpecs)
		}
	}
	proxyCommand := `printf '%s' "$HTTP_PROXY"`
	if runtime.GOOS == "windows" {
		proxyCommand = `Write-Output $env:HTTP_PROXY`
	}
	arguments, err := json.Marshal(map[string]any{"cmd": proxyCommand, "environment_id": "remote-secondary", "yield_time_ms": 1000})
	if err != nil {
		t.Fatal(err)
	}
	output, err := toolRouter.Dispatch(context.Background(), &tool.Invocation{
		CallID:   "call-remote-environment",
		ToolName: tool.PlainName(tool.DefaultExecCommandToolName),
		Payload:  tool.Payload{Kind: tool.PayloadFunction, Arguments: string(arguments)},
	})
	if err != nil {
		t.Fatalf("remote exec dispatch error = %v", err)
	}
	if output == nil || output.Data["exit_code"] != 0 {
		t.Fatalf("remote exec output = %#v", output)
	}
	router.managedNetworksMu.Lock()
	managed := router.managedNetworks[params.ThreadID]
	router.managedNetworksMu.Unlock()
	if managed == nil {
		t.Fatal("thread managed network was not started")
	}
	controllerProxy := managed.EnvSnapshot()["HTTP_PROXY"]
	if controllerProxy == "" {
		t.Fatal("controller managed network did not expose its local proxy")
	}
	if strings.Contains(output.Body, controllerProxy) {
		t.Fatalf("controller-local proxy leaked into remote output: proxy=%q output=%q", controllerProxy, output.Body)
	}
	if runtime.GOOS == "windows" {
		if strings.Contains(output.Body, "http://127.0.0.1:") {
			t.Fatalf("native Windows remote launch should stay direct without a sandbox token: %q", output.Body)
		}
	} else if !strings.Contains(output.Body, "http://127.0.0.1:") {
		t.Fatalf("remote output did not use an executor-local proxy: %q", output.Body)
	}
}

