func TestRuntimeRouterSkillsContextDoesNotWarnForUnselectedMCPDependenciesLikeRust(t *testing.T) {
	skillsRoot := t.TempDir()
	skillDir := filepath.Join(skillsRoot, "calendar-skill")
	if err := os.MkdirAll(filepath.Join(skillDir, SkillMetadataDir), 0o755); err != nil {
		t.Fatalf("MkdirAll(skill metadata) error = %v", err)
	}
	if err := os.WriteFile(filepath.Join(skillDir, SkillFilename), []byte("---\nname: calendar-skill\ndescription: Calendar helper\n---\n"), 0o600); err != nil {
		t.Fatalf("WriteFile(skill) error = %v", err)
	}
	if err := os.WriteFile(filepath.Join(skillDir, SkillMetadataDir, SkillMetadataFilename), []byte(`
dependencies:
  tools:
    - type: mcp
      value: calendar
      url: https://mcp.example.test
`), 0o600); err != nil {
		t.Fatalf("WriteFile(skill metadata) error = %v", err)
	}

	sink := NewNotificationBuffer()
	router := NewRuntimeRouter(RuntimeServices{Skills: NewSkillsService([]string{skillsRoot})})
	router.SetNotificationSink(sink)
	if _, _, _, err := router.instructionsWithSkillsContext("thread-skills", &config.Config{Values: map[string]any{}}, &turn.TurnStartParams{}, "base"); err != nil {
		t.Fatalf("instructionsWithSkillsContext() error = %v", err)
	}
	warnings := warningNotificationsForTest(sink)
	if len(warnings) != 0 {
		t.Fatalf("unselected dependency warnings = %+v, want none", warnings)
	}

	configuredSink := NewNotificationBuffer()
	configured := NewRuntimeRouter(RuntimeServices{Skills: NewSkillsService([]string{skillsRoot})})
	configured.SetNotificationSink(configuredSink)
	cfg := &config.Config{Values: map[string]any{
		"mcp_servers": map[string]any{
			"calendar": map[string]any{"url": "https://mcp.example.test"},
		},
	}}
	if _, _, _, err := configured.instructionsWithSkillsContext("thread-skills", cfg, &turn.TurnStartParams{}, "base"); err != nil {
		t.Fatalf("instructionsWithSkillsContext(configured) error = %v", err)
	}
	if warnings := warningNotificationsForTest(configuredSink); len(warnings) != 0 {
		t.Fatalf("configured warnings = %+v, want none", warnings)
	}
}

func warningNotificationsForTest(sink *NotificationBuffer) []*WarningNotification {
	if sink == nil {
		return nil
	}
	var out []*WarningNotification
	for _, notification := range sink.List() {
		if notification.Method != NotificationWarning {
			continue
		}
		warning, ok := notification.Params.(*WarningNotification)
		if ok {
			out = append(out, warning)
		}
	}
	return out
}

func TestResponsesStreamRetryUsesRustErrorNotificationShape(t *testing.T) {
	sink := NewNotificationBuffer()
	router := NewRuntimeRouter(RuntimeServices{})
	router.SetNotificationSink(sink)
	state := newResponsesStreamNotificationState(false, "turn-retry")
	status := uint16(http.StatusServiceUnavailable)

	router.notifyResponsesStreamEvent("thread-retry", "turn-retry", &model.ResponsesStreamEvent{
		Kind:            model.ResponsesStreamEventRetrying,
		RetryAttempt:    2,
		RetryMax:        5,
		RetryError:      "stream closed",
		RetryHTTPStatus: &status,
	}, state)

	notifications := sink.List()
	if len(notifications) != 1 || notifications[0].Method != NotificationError {
		t.Fatalf("notifications = %#v, want one error notification", notifications)
	}
	payload, ok := notifications[0].Params.(*ErrorNotification)
	if !ok || !payload.WillRetry || payload.ThreadID != "thread-retry" || payload.TurnID != "turn-retry" {
		t.Fatalf("payload = %#v", notifications[0].Params)
	}
	if payload.Error.Message != "Reconnecting... 2/5" || payload.Error.AdditionalDetails == nil || *payload.Error.AdditionalDetails != "stream closed" {
		t.Fatalf("turn error = %#v", payload.Error)
	}
	info, ok := payload.Error.CodexErrorInfo.(map[string]any)
	if !ok || info["responseStreamDisconnected"] == nil {
		t.Fatalf("codexErrorInfo = %#v", payload.Error.CodexErrorInfo)
	}
}

func TestResponsesStreamPreservesCommentaryPhaseForTUIBoundary(t *testing.T) {
	sink := NewNotificationBuffer()
	router := NewRuntimeRouter(RuntimeServices{})
	router.SetNotificationSink(sink)
	state := newResponsesStreamNotificationState(false, "turn-weather")
	commentary := &model.AgentItem{ID: "msg-commentary", Type: "agent_message", Text: "我先查询天气。", Data: map[string]any{"phase": "commentary"}}

	router.notifyResponsesStreamEvent("thread-weather", "turn-weather", &model.ResponsesStreamEvent{Kind: model.ResponsesStreamEventOutputAdded, ItemID: commentary.ID, Item: commentary}, state)
	router.notifyResponsesStreamEvent("thread-weather", "turn-weather", &model.ResponsesStreamEvent{Kind: model.ResponsesStreamEventOutputText, ItemID: commentary.ID, Delta: commentary.Text}, state)
	router.notifyResponsesStreamEvent("thread-weather", "turn-weather", &model.ResponsesStreamEvent{Kind: model.ResponsesStreamEventOutputAdded, ItemID: "call-weather", Item: &model.AgentItem{ID: "call-weather", Type: "function_call", Name: tool.DefaultExecCommandToolName, CallID: "call-weather", Arguments: `{"cmd":"curl weather"}`}}, state)

	notifications := sink.List()
	commentaryAt, toolAt := -1, -1
	for index, notification := range notifications {
		switch notification.Method {
		case NotificationItemStarted:
			payload, _ := notification.Params.(*ItemStartedNotification)
			if payload != nil && payload.Item["id"] == commentary.ID {
				commentaryAt = index
				if payload.Item["phase"] != "commentary" {
					t.Fatalf("commentary phase = %#v", payload.Item["phase"])
				}
			} else if payload != nil && payload.Item["id"] == "call-weather" {
				toolAt = index
			}
		}
	}
	if commentaryAt < 0 || toolAt < 0 || commentaryAt >= toolAt {
		t.Fatalf("notifications = %#v; commentaryAt=%d toolAt=%d", notifications, commentaryAt, toolAt)
	}
}

